@startuml

class Kinepolis {
}

class Cinema {
  + Town : string
}

class Theatre {
  + Number : int
}

class MovieCopy {
  + Id : int
}

class Show {
  + StartTime : datetime
  + EndTime : datetime
  + publish()
  + cancelShow()
}

class Reservation {
  + ReservationTime : datetime
}

class Ticket {
  + SeatNumber : int
}

class Customer {
  + Name : string
}

class AlternativeOffer {
  + ExpiryTime : datetime
  + accept()
  + decline()
  + expire()
}

