Show "1" -- "0..*" Reservation
Show "1" -- "0..*" Ticket
Customer "1" -- "0..*" Reservation
Customer "1" -- "0..*" AlternativeOffer
Show "1" -- "0..*" AlternativeOffer
Show "1" -- "0..*" Ticket

@enduml

